754	    /// Render the processing state with centered progress
755	    fn render_processing(&self, frame: &mut Frame, area: Rect, step: GitHubSetupStep) {
756	        let t = theme();
757	
758	        // Center the progress box
759	        // Height: 8 steps + plus 1 unified padding = 10
760	        let popup_width = 50u16.min(area.width.saturating_sub(4));
761	        let popup_height = 30u16.min(area.height.saturating_sub(2));
762	        let popup_area = crate::utils::center_popup(area, popup_width, popup_height);
763	
764	        // Clear the popup area
765	        frame.render_widget(Clear, popup_area);
766	
767	        // Build progress content
768	        let steps = [
769	            (GitHubSetupStep::Connecting, "Connecting to GitHub"),
770	            (GitHubSetupStep::ValidatingToken, "Validating token"),
771	            (GitHubSetupStep::CheckingRepo, "Checking repository"),
772	            (GitHubSetupStep::CloningRepo, "Cloning repository"),
773	            (GitHubSetupStep::CreatingRepo, "Creating repository"),
774	            (GitHubSetupStep::InitializingRepo, "Initializing repository"),
775	            (GitHubSetupStep::DiscoveringProfiles, "Discovering profiles"),
776	            (GitHubSetupStep::Complete, "Complete"),
777	        ];
778	
779	        let current_step_index = steps.iter().position(|(s, _)| *s == step).unwrap_or(0);
780	
781	        let mut lines: Vec<Line> = Vec::new();
782	        lines.push(Line::from(""));
783	
784	        for (i, (_, label)) in steps.iter().enumerate() {
785	            let (prefix, style) = if i < current_step_index {
786	                ("✓ ", Style::default().fg(t.success))
787	            } else if i == current_step_index {
788	                (
789	                    "→ ",
790	                    Style::default().fg(t.primary).add_modifier(Modifier::BOLD),
791	                )
792	            } else {
793	                ("  ", t.muted_style())
794	            };
795	
796	            lines.push(Line::from(vec![
797	                Span::styled(prefix, style),
798	                Span::styled(*label, style),
799	            ]));
800	        }
801	
802	        // Add status message if any
803	        if let Some(ref status) = self.state.status_message {
804	            lines.push(Line::from(""));
805	            lines.push(Line::from(Span::styled(
806	                status.as_str(),
807	                Style::default().fg(t.text),
808	            )));
809	        }
810	
811	        let progress_block = Block::default()
812	            .borders(Borders::ALL)
813	            .title(" Setting Up Repository ")
814	            .title_alignment(Alignment::Center)
815	            .border_style(Style::default().fg(t.primary))
816	            .border_type(t.border_type(true))
817	            .padding(Padding::proportional(1))
818	            .style(t.background_style());
819	
820	        let para = Paragraph::new(lines)
821	            .block(progress_block)
822	            .wrap(Wrap { trim: true });
823	
824	        frame.render_widget(para, popup_area);
825	    }
