1252	    fn handle_sha256_confirm_event(&mut self, event: Event, ctx: &ScreenContext) -> ScreenAction {
1253	        match event {
1254	            Event::Key(key) if key.kind == KeyEventKind::Press => {
1255	                match ctx.config.keymap.get_action(key.code, key.modifiers) {
1256	                    Some(Action::Confirm) => {
