1377	    fn handle_event(&mut self, event: Event, ctx: &ScreenContext) -> Result<ScreenAction> {
1378	        // Modal: experimental SHA-256 confirmation gate (issue #35). Intercept
1379	        // all input while open so the choice is explicit and background is blocked.
