1381	            return Ok(self.handle_sha256_confirm_event(event, ctx));
1382	        }
1383	
1384	        self.state.error_message = None;
1385	
1386	        match event {
1387	            Event::Key(key) if key.kind == KeyEventKind::Press => {
1388	                let action = ctx.config.keymap.get_action(key.code, key.modifiers);
1389	
1390	                match self.state.focus {
1391	                    StorageSetupFocus::MethodList => self.handle_list_event(action),
1392	                    StorageSetupFocus::Form => self.handle_form_event(key, ctx),
1393	                }
1394	            }
1395	            Event::Mouse(mouse) => self.handle_mouse_event(mouse),
1396	            _ => Ok(ScreenAction::None),
1397	        }
1398	    }
