217	    /// Process a profile selection action.
218	    ///
219	    /// This method dispatches actions to the appropriate handler methods.
220	    ///
221	    /// # Arguments
222	    ///
223	    /// * `action` - The action to process.
224	    /// * `config` - Mutable reference to the application configuration.
225	    /// * `config_path` - Path to the configuration file.
226	    ///
227	    /// # Returns
228	    ///
229	    /// An `ActionResult` indicating the outcome of the action.
230	    pub fn process_action(
231	        &mut self,
232	        action: ProfileSelectionAction,
233	        config: &mut Config,
234	        config_path: &Path,
235	    ) -> Result<ActionResult> {
236	        match action {
237	            ProfileSelectionAction::CreateAndActivateProfile { name } => {
238	                // First create the profile
239	                match ProfileService::create_profile(&config.repo_path, &name, None, None, None) {
240	                    Ok(sanitized_name) => {
241	                        info!("Created profile '{}' during setup", sanitized_name);
242	                        // Then activate it
243	                        self.activate_profile(config, config_path, &sanitized_name)
244	                    }
245	                    Err(e) => {
246	                        error!("Failed to create profile '{}': {}", name, e);
247	                        Ok(ActionResult::ShowDialog {
248	                            title: "Profile Creation Failed".to_string(),
249	                            content: format!("Failed to create profile '{name}': {e}"),
250	                            variant: DialogVariant::Error,
251	                        })
252	                    }
253	                }
254	            }
255	            ProfileSelectionAction::ActivateProfile { name } => {
256	                self.activate_profile(config, config_path, &name)
257	            }
258	        }
259	    }
260	
261	    /// Activate a profile and navigate to the main menu.
262	    ///
263	    /// This method sets the active profile in config, saves the config,
264	    /// calls `ProfileService` to activate the profile (create symlinks),
265	    /// marks the profile as activated, and navigates to the main menu.
266	    ///
267	    /// # Arguments
268	    ///
269	    /// * `config` - Mutable reference to the application configuration.
270	    /// * `config_path` - Path to the configuration file.
271	    /// * `profile_name` - Name of the profile to activate.
272	    ///
273	    /// # Returns
274	    ///
275	    /// An `ActionResult` indicating navigation or error dialog.
276	    fn activate_profile(
277	        &mut self,
278	        config: &mut Config,
279	        config_path: &Path,
280	        profile_name: &str,
281	    ) -> Result<ActionResult> {
282	        // Set active profile and save config
283	        config.active_profile = profile_name.to_string();
284	        if let Err(e) = config.save(config_path) {
285	            error!("Failed to save config with active profile: {}", e);
286	            return Ok(ActionResult::ShowDialog {
287	                title: "Configuration Error".to_string(),
288	                content: format!("Failed to save configuration: {e}"),
289	                variant: DialogVariant::Error,
290	            });
291	        }
292	
293	        // Call ProfileService to activate the profile (create symlinks)
294	        match ProfileService::activate_profile(
295	            &config.repo_path,
296	            profile_name,
297	            config.backup_enabled,
298	        ) {
299	            Ok(result) => {
300	                info!(
301	                    "Activated profile '{}' with {} files",
302	                    profile_name, result.success_count
303	                );
304	
305	                // Mark as activated and save config again
306	                config.profile_activated = true;
307	                if let Err(e) = config.save(config_path) {
308	                    error!("Failed to save config after activation: {}", e);
309	                    return Ok(ActionResult::ShowDialog {
310	                        title: "Configuration Error".to_string(),
311	                        content: format!("Failed to save configuration after activation: {e}"),
312	                        variant: DialogVariant::Error,
313	                    });
314	                }
315	
316	                // Reset screen state
317	                self.reset();
318	
319	                // Navigate to main menu
320	                Ok(ActionResult::Navigate(ScreenId::MainMenu))
321	            }
322	            Err(e) => {
323	                error!("Failed to activate profile '{}': {}", profile_name, e);
324	                Ok(ActionResult::ShowDialog {
325	                    title: "Activation Failed".to_string(),
326	                    content: format!("Failed to activate profile '{profile_name}': {e}"),
327	                    variant: DialogVariant::Error,
328	                })
329	            }
330	        }
