341	    fn render(&mut self, frame: &mut Frame, area: Rect, ctx: &RenderContext) -> Result<()> {
342	        // Background
343	        let t = crate::styles::theme();
344	        let background = ratatui::widgets::Block::default().style(t.background_style());
345	        frame.render_widget(background, area);
346	
347	        // Always render main content first
348	        if self.state.show_create_popup {
349	            self.render_create_popup(frame, area, ctx.config);
350	        } else {
351	            self.render_profile_list(frame, area, ctx.config);
352	        }
353	
354	        // Render dialogs on top of the content (not instead of it)
355	        if self.state.show_exit_warning {
356	            self.render_exit_warning(frame, area, ctx.config);
357	        }
358	
