361	
362	    fn handle_event(&mut self, event: Event, ctx: &ScreenContext) -> Result<ScreenAction> {
363	        // Handle exit warning
364	        if self.state.show_exit_warning {
365	            if let Event::Key(key) = event {
366	                if key.kind == KeyEventKind::Press && key.code == KeyCode::Esc {
367	                    self.state.show_exit_warning = false;
368	                    self.reset();
369	                    return Ok(ScreenAction::Navigate(ScreenId::MainMenu));
370	                }
371	            }
372	            return Ok(ScreenAction::None);
373	        }
374	
375	        // Handle mouse events (only on main list, not popup)
376	        if let Event::Mouse(mouse) = event {
377	            if !self.state.show_create_popup {
378	                match mouse.kind {
379	                    MouseEventKind::Down(MouseButton::Left) => {
380	                        if let Some(&idx) = self.mouse_regions.hit_test(mouse.column, mouse.row) {
381	                            self.state.list_state.select(Some(idx));
382	                            if idx == self.state.profiles.len() {
383	                                self.state.show_create_popup = true;
384	                                self.state.create_name_input.clear();
385	                            } else if let Some(name) = self.state.profiles.get(idx) {
386	                                let name = name.clone();
387	                                return Ok(ScreenAction::ActivateProfile { name });
388	                            }
389	                        }
390	                    }
391	                    MouseEventKind::ScrollUp => {
392	                        if let Some(area) = self.list_area {
393	                            if area
394	                                .contains(ratatui::layout::Position::new(mouse.column, mouse.row))
395	                            {
396	                                if let Some(current) = self.state.list_state.selected() {
397	                                    let new = current.saturating_sub(3);
398	                                    self.state.list_state.select(Some(new));
399	                                }
400	                            }
401	                        }
402	                    }
403	                    MouseEventKind::ScrollDown => {
404	                        if let Some(area) = self.list_area {
405	                            if area
406	                                .contains(ratatui::layout::Position::new(mouse.column, mouse.row))
407	                            {
408	                                if let Some(current) = self.state.list_state.selected() {
409	                                    let max = self.state.profiles.len(); // includes "Create New"
410	                                    let new = (current + 3).min(max);
411	                                    self.state.list_state.select(Some(new));
412	                                }
413	                            }
414	                        }
415	                    }
416	                    _ => {}
417	                }
418	            }
419	            return Ok(ScreenAction::None);
420	        }
421	
422	        if let Event::Key(key) = event {
423	            if key.kind != KeyEventKind::Press {
424	                return Ok(ScreenAction::None);
425	            }
426	
427	            // When popup is shown, handle character input FIRST
428	            // This ensures vim bindings like h/l/j/k don't interfere with typing
429	            if self.state.show_create_popup {
430	                if let KeyCode::Char(c) = key.code {
431	                    if !key
432	                        .modifiers
433	                        .intersects(KeyModifiers::CONTROL | KeyModifiers::ALT | KeyModifiers::SUPER)
434	                    {
435	                        self.state.create_name_input.insert_char(c);
436	                        return Ok(ScreenAction::Refresh);
437	                    }
438	                }
439	            }
440	
441	            let action = ctx.config.keymap.get_action(key.code, key.modifiers);
442	
443	            if let Some(action) = action {
444	                use crate::keymap::Action;
445	
446	                // Handle popup-specific actions
447	                if self.state.show_create_popup {
448	                    match action {
449	                        Action::Confirm => {
450	                            let profile_name =
451	                                self.state.create_name_input.text_trimmed().to_string();
452	                            if !profile_name.is_empty() {
453	                                self.state.show_create_popup = false;
454	                                return Ok(ScreenAction::CreateAndActivateProfile {
455	                                    name: profile_name,
456	                                });
457	                            }
458	                            return Ok(ScreenAction::None);
459	                        }
460	                        Action::Cancel => {
461	                            self.state.show_create_popup = false;
462	                            self.state.create_name_input.clear();
463	                            return Ok(ScreenAction::Refresh);
464	                        }
465	                        _ => {
466	                            // Forward navigation and editing actions to the input
467	                            self.state.create_name_input.handle_action(action);
468	                            return Ok(ScreenAction::Refresh);
469	                        }
470	                    }
471	                }
472	
473	                // Handle list navigation (not in popup)
474	                match action {
475	                    Action::MoveUp => {
476	                        if let Some(current) = self.state.list_state.selected() {
477	                            if current > 0 {
478	                                self.state.list_state.select(Some(current - 1));
479	                            } else {
480	                                // Wrap to bottom (including create option)
481	                                self.state
482	                                    .list_state
483	                                    .select(Some(self.state.profiles.len()));
484	                            }
485	                        } else if !self.state.profiles.is_empty() {
486	                            self.state
487	                                .list_state
488	                                .select(Some(self.state.profiles.len()));
489	                        }
490	                    }
491	                    Action::MoveDown => {
492	                        if let Some(current) = self.state.list_state.selected() {
493	                            if current < self.state.profiles.len() {
494	                                self.state.list_state.select(Some(current + 1));
495	                            } else {
496	                                // Wrap to top
497	                                self.state.list_state.select(Some(0));
498	                            }
499	                        } else if !self.state.profiles.is_empty() {
500	                            self.state.list_state.select(Some(0));
501	                        }
502	                    }
503	                    Action::Confirm => {
504	                        if let Some(idx) = self.state.list_state.selected() {
505	                            if idx == self.state.profiles.len() {
506	                                // "Create New Profile" selected
507	                                self.state.show_create_popup = true;
508	                                self.state.create_name_input.clear();
509	                            } else if let Some(name) = self.state.profiles.get(idx) {
510	                                let name = name.clone();
511	                                return Ok(ScreenAction::ActivateProfile { name });
512	                            }
513	                        }
514	                    }
515	                    Action::Quit | Action::Cancel => {
516	                        self.state.show_exit_warning = true;
517	                    }
518	                    _ => {}
519	                }
520	            }
521	        }
522	
523	        Ok(ScreenAction::None)
524	    }
525	
526	    fn is_input_focused(&self) -> bool {
527	        self.state.show_create_popup
528	    }
529	}
