144	    /// Process periodic tasks (package checking, installation monitoring, import discovery)
145	    /// Returns `ScreenAction::Refresh` if a redraw is needed
146	    pub fn tick(&mut self) -> Result<ScreenAction> {
147	        let mut needs_redraw = false;
148	
149	        // 1. Process Package Checking
150	        if self.state.is_checking {
151	            // Check delay
152	            if let Some(delay_until) = self.state.checking_delay_until {
153	                if std::time::Instant::now() >= delay_until {
154	                    self.state.checking_delay_until = None;
155	                    self.process_package_check_step()?;
156	                    needs_redraw = true;
157	                }
158	            } else {
159	                self.process_package_check_step()?;
160	                needs_redraw = true;
161	            }
162	        }
163	
164	        // 2. Process Installation
165	        if !matches!(self.state.installation_step, InstallationStep::NotStarted) {
166	            self.process_installation_step()?;
167	            needs_redraw = true;
168	        }
169	
170	        // 3. Process Import Discovery (async polling)
171	        if self.state.import_loading {
172	            // Tick the spinner animation
173	            self.state.import_spinner_tick = self.state.import_spinner_tick.wrapping_add(1);
174	            // Poll async discovery (non-blocking)
175	            self.poll_import_discovery();
176	            needs_redraw = true;
177	        }
178	
179	        if needs_redraw {
180	            Ok(ScreenAction::Refresh)
181	        } else {
182	            Ok(ScreenAction::None)
183	        }
184	    }
185	
186	    fn process_package_check_step(&mut self) -> Result<()> {
187	        let state = &mut self.state;
188	
189	        if state.packages.is_empty() {
190	            state.is_checking = false;
191	            return Ok(());
192	        }
193	
194	        // Initialize statuses if needed
195	        if state.package_statuses.len() != state.packages.len() {
196	            state.package_statuses = vec![PackageStatus::Unknown; state.packages.len()];
197	        }
198	
199	        // STEP 1: If we have a target package to check, check it now.
200	        if let Some(index) = state.checking_index {
201	            if index < state.packages.len() {
202	                let package = &state.packages[index];
203	                debug!("Checking package: {} (index: {})", package.name, index);
204	
205	                let check_result = PackageInstaller::check_exists(package);
206	                let pkg_name = package.name.clone();
207	                let pkg_manager = package.manager.clone();
208	
209	                match check_result {
210	                    Ok((exists, check_cmd, output)) => {
211	                        // Update cache
212	                        if !state.active_profile.is_empty() {
213	                            if let Err(e) = state.cache.update_status(
214	                                &state.active_profile,
215	                                &pkg_name,
216	                                exists,
217	                                check_cmd.clone(),
218	                                output.clone(),
219	                            ) {
220	                                warn!("Failed to update package cache: {}", e);
221	                            }
222	                        }
223	
224	                        if exists {
225	                            state.package_statuses[index] = PackageStatus::Installed;
226	                        } else if !PackageManagerImpl::is_manager_installed(&pkg_manager) {
227	                            state.package_statuses[index] = PackageStatus::Error(format!(
228	                                "Package not found and package manager '{pkg_manager:?}' is not installed"
229	                            ));
230	                        } else {
231	                            state.package_statuses[index] = PackageStatus::NotInstalled;
232	                        }
233	                    }
234	                    Err(e) => {
235	                        error!("Error checking package {}: {}", pkg_name, e);
236	                        state.package_statuses[index] = PackageStatus::Error(e.to_string());
237	                    }
238	                }
239	            }
240	
241	            // Store the index we just checked before clearing it
242	            let checked_index = index;
243	            state.checking_index = None;
244	
245	            info!(
246	                "Finished checking selected package at index {}",
247	                checked_index
248	            );
249	            return Ok(());
250	        }
251	
252	        // STEP 2: Look for more work (next 'Unknown' package)
253	        // This only runs for "check all" mode (when checking_index was None initially)
254	        if let Some(index) = state
255	            .package_statuses
256	            .iter()
257	            .position(|s| matches!(s, PackageStatus::Unknown))
258	        {
259	            // Found work: Set checking_index so the loading icon shows for this package
260	            state.checking_index = Some(index);
261	
262	            // Schedule delay to let UI render the Loading icon for this index before we check it
263	            state.checking_delay_until =
264	                Some(std::time::Instant::now() + Duration::from_millis(10));
265	            return Ok(());
266	        }
267	
268	        // STEP 3: No work left
269	        state.is_checking = false;
270	        state.checking_index = None;
271	        info!("Finished checking all packages");
272	
273	        // Check if we just finished checking a newly added package
274	        // If it's not installed, prompt the user to install it
275	        if let Some(new_idx) = state.newly_added_index.take() {
276	            if let Some(status) = state.package_statuses.get(new_idx) {
277	                if matches!(status, PackageStatus::NotInstalled) {
278	                    info!(
279	                        "Newly added package at index {} is not installed, prompting to install",
280	                        new_idx
281	                    );
282	                    state.popup_type = PackagePopupType::InstallMissing;
283	                }
284	            }
285	        }
286	
287	        Ok(())
288	    }
289	
290	    fn process_installation_step(&mut self) -> Result<()> {
291	        // Logic ported from app.rs process_installation_step
292	        // We'll need to implement the async parts. The tricky part is the Receiver.
293	        // It's part of the state enum InstallationStep::Installing { status_rx, ... }
294	        // But `PackageManagerState` in `ui_state.rs` defines `status_rx` as `Option<Receiver<...>>`.
295	        // So we can access it here!
296	
297	        let state = &mut self.state;
298	        if let InstallationStep::Installing {
299	            package_index,
300	            package_name,
301	            total_packages: _,
302	            packages_to_install: _,
303	            installed,
304	            failed,
305	            status_rx,
306	        } = &mut state.installation_step
307	        {
308	            // Check for initial delay
309	            if let Some(delay) = state.installation_delay_until {
310	                if std::time::Instant::now() < delay {
311	                    return Ok(());
312	                }
313	                state.installation_delay_until = None;
314	
315	                // Start installation if not started (rx is None)
316	                if status_rx.is_none() {
317	                    info!("Starting installation for package: {}", package_name);
318	                    // Need to get the actual package
319	                    let pkg = if let Some(p) = state.packages.get(*package_index) {
320	                        p.clone()
321	                    } else {
322	                        // Error case
323	                        error!("Package index {} out of bounds", package_index);
324	                        failed.push((*package_index, "Package index out of bounds".to_string()));
325	                        // Move to next
326	                        self.advance_installation()?;
327	                        return Ok(());
328	                    };
329	
330	                    // Spawn installation thread
331	                    let (tx, rx) = std::sync::mpsc::channel();
332	                    let pkg_clone = pkg.clone();
333	                    std::thread::spawn(move || {
334	                        PackageInstaller::install(&pkg_clone, tx);
335	                    });
336	                    *status_rx = Some(rx);
337	                }
338	            }
339	
340	            // Check for result
341	            let mut finished_current = false;
342	            if let Some(rx) = status_rx {
343	                // Drain available messages
344	                loop {
345	                    match rx.try_recv() {
346	                        Ok(result) => {
347	                            match result {
348	                                InstallationStatus::Output(line) => {
349	                                    state.installation_output.push(line);
350	                                }
351	                                InstallationStatus::Complete { success, error } => {
352	                                    finished_current = true;
353	                                    if success {
354	                                        info!("Successfully installed {}", package_name);
355	                                        installed.push(*package_index);
356	                                        state
357	                                            .installation_output
358	                                            .push(format!("✅ Installed {package_name}"));
359	                                        // Update status in list
360	                                        if *package_index < state.package_statuses.len() {
361	                                            state.package_statuses[*package_index] =
362	                                                PackageStatus::Installed;
363	                                        }
364	
365	                                        // Update cache
366	                                        if !state.active_profile.is_empty() {
367	                                            if let Err(e) = state.cache.update_status(
368	                                                &state.active_profile,
369	                                                package_name,
370	                                                true,
371	                                                None,
372	                                                Some("Successfully installed".to_string()),
373	                                            ) {
374	                                                warn!("Failed to update package cache: {}", e);
375	                                            }
376	                                        }
377	                                    } else {
378	                                        let err_msg =
379	                                            error.unwrap_or_else(|| "Unknown error".to_string());
380	                                        error!("Failed to install {}: {}", package_name, err_msg);
381	                                        failed.push((*package_index, err_msg.clone()));
382	                                        state.installation_output.push(format!(
383	                                            "❌ Failed to install {package_name}: {err_msg}"
384	                                        ));
385	                                    }
386	                                    // Break after Complete to avoid hitting Disconnected
387	                                    break;
388	                                }
389	                            }
390	                        }
391	                        Err(std::sync::mpsc::TryRecvError::Empty) => {
392	                            break;
393	                        }
394	                        Err(std::sync::mpsc::TryRecvError::Disconnected) => {
395	                            // Thread died?
396	                            finished_current = true;
397	                            failed.push((
398	                                *package_index,
399	                                "Installation thread disconnected".to_string(),
400	                            ));
401	                            break;
402	                        }
403	                    }
404	                }
405	            }
406	
407	            if finished_current {
408	                self.advance_installation()?;
409	            }
410	        } else if let InstallationStep::Complete { .. } = &state.installation_step {
411	            // Already complete, nothing to tick
412	        }
413	
414	        Ok(())
415	    }
416	
417	    fn advance_installation(&mut self) -> Result<()> {
418	        // Logic to move to next package or finish
419	        // We have to destruct and reconstruct state carefully due to ownership
420	        // Or strictly manipulate the fields inside the match guard if we used a struct, but it's an enum.
421	        // We'll clone necessary implementation details to move state forward.
422	
423	        // We are inside `process_installation_step` which has mutable borrow.
424	        // Calling this helper requires splitting borrows or careful logic.
425	        // Let's implement logic inline or carefully.
426	        // Actually, simpler: clone 'packages_to_install', 'installed', 'failed' etc. then re-assign state.
427	
428	        let state = &mut self.state;
429	        // Extract needed data to decide next step
430	        let (next_packages, installed_list, failed_list, total) =
431	            if let InstallationStep::Installing {
432	                packages_to_install,
433	                installed,
434	                failed,
435	                total_packages,
436	                ..
437	            } = &state.installation_step
438	            {
439	                (
440	                    packages_to_install.clone(),
441	                    installed.clone(),
442	                    failed.clone(),
443	                    *total_packages,
444	                )
445	            } else {
446	                return Ok(());
447	            };
448	
449	        if next_packages.is_empty() {
450	            // Done
451	            state.installation_step = InstallationStep::Complete {
452	                installed: installed_list,
453	                failed: failed_list,
454	            };
455	        } else {
456	            // Process next
457	            let next_idx = next_packages[0];
458	            let remaining = next_packages[1..].to_vec();
459	            let pkg_name = if let Some(p) = state.packages.get(next_idx) {
460	                p.name.clone()
461	            } else {
462	                "Unknown".to_string()
463	            };
464	
465	            state.installation_step = InstallationStep::Installing {
466	                package_index: next_idx,
467	                package_name: pkg_name,
468	                total_packages: total,
469	                packages_to_install: remaining,
470	                installed: installed_list,
471	                failed: failed_list,
472	                status_rx: None,
473	            };
474	            state.installation_delay_until =
475	                Some(std::time::Instant::now() + Duration::from_millis(500));
476	        }
477	
478	        Ok(())
479	    }
480	}
