556	    fn handle_event(&mut self, event: Event, ctx: &ScreenContext) -> Result<ScreenAction> {
557	        let config = ctx.config;
558	
559	        // If installation is in progress (and not complete), blocking input except maybe quit?
560	        // App.rs checks `installation_step` to show progress.
561	        if matches!(
562	            self.state.installation_step,
563	            InstallationStep::Installing { .. }
564	        ) {
565	            // Block generic input, maybe allow generic Quit via App?
566	            // But actually, we just ignore most keys.
567	            return Ok(ScreenAction::None);
568	        }
569	
570	        // If installation complete, any key closes it
571	        if let InstallationStep::Complete { .. } = self.state.installation_step {
572	            if let Event::Key(_) = event {
573	                self.state.installation_step = InstallationStep::NotStarted;
574	                self.state.installation_output.clear();
575	                self.state.installation_output_scroll = 0;
576	                return Ok(ScreenAction::Refresh);
577	            }
578	            return Ok(ScreenAction::None);
579	        }
580	
581	        // Popups consume all events
582	        if self.state.popup_type != PackagePopupType::None {
583	            match event {
584	                Event::Key(key) => match self.state.popup_type {
585	                    PackagePopupType::Add | PackagePopupType::Edit => {
586	                        return self.handle_add_edit_popup_event(key, config);
587	                    }
588	                    PackagePopupType::Delete => {
589	                        return self.handle_delete_popup_event(key, config);
590	                    }
591	                    PackagePopupType::InstallMissing => {
592	                        if let Some(action) =
593	                            self.get_action(key.code, key.modifiers, &config.keymap)
594	                        {
595	                            match action {
596	                                Action::Confirm => {
597	                                    self.state.popup_type = PackagePopupType::None;
598	                                    return Ok(ScreenAction::InstallMissingPackages);
599	                                }
600	                                Action::Cancel | Action::Quit => {
601	                                    self.state.popup_type = PackagePopupType::None;
602	                                    return Ok(ScreenAction::Refresh);
603	                                }
604	                                _ => {}
605	                            }
606	                        }
607	                        return Ok(ScreenAction::None);
608	                    }
609	                    PackagePopupType::Import => {
610	                        return self.handle_import_popup_event(key, config);
611	                    }
612	                    PackagePopupType::None => unreachable!(),
613	                },
614	                Event::Mouse(mouse) => {
615	                    return self.handle_popup_mouse_event(mouse);
616	                }
617	                _ => {}
618	            }
619	            return Ok(ScreenAction::None);
620	        }
621	
622	        match event {
623	            Event::Key(key) => {
624	                if let Some(action) = self.get_action(key.code, key.modifiers, &config.keymap) {
625	                    return self.handle_main_list_action(action);
626	                }
627	            }
628	            Event::Mouse(mouse) => {
629	                return self.handle_mouse_event(mouse);
630	            }
631	            _ => {}
632	        }
633	        Ok(ScreenAction::None)
634	    }
