707	                    if let Some(area) = self.import_tabs_area {
708	                        if area.contains(pos) {
709	                            self.state.import_focus = ImportFocus::Tabs;
710	                            // Calculate which tab was clicked based on x-position
711	                            // Each tab label is "  {name}  " with " " divider
712	                            let mut x_offset = area.x;
713	                            for (i, source) in
714	                                self.state.import_available_sources.iter().enumerate()
715	                            {
716	                                let tab_width = (source.display_name().len() + 4) as u16; // "  name  "
717	                                let divider_width = if i > 0 { 1 } else { 0 }; // " " divider
718	                                let start = x_offset + divider_width;
719	                                let end = start + tab_width;
