787	    fn handle_main_list_action(&mut self, action: Action) -> Result<ScreenAction> {
788	        let state = &mut self.state;
789	        match action {
790	            Action::MoveUp if !state.is_checking => {
791	                state.list_state.select_previous();
792	                return Ok(ScreenAction::Refresh);
793	            }
794	            Action::MoveDown if !state.is_checking => {
795	                state.list_state.select_next();
796	                return Ok(ScreenAction::Refresh);
797	            }
798	            Action::Refresh
799	                if state.popup_type == PackagePopupType::None
800	                    && !state.is_checking
801	                    && !state.packages.is_empty() =>
802	            {
803	                // Check All
804	                // Initialize check all
805	                if state.package_statuses.len() != state.packages.len() {
806	                    state.package_statuses = vec![PackageStatus::Unknown; state.packages.len()];
807	                }
808	                state.package_statuses = vec![PackageStatus::Unknown; state.packages.len()];
809	                state.is_checking = true;
810	                state.checking_index = None;
811	                state.checking_delay_until =
812	                    Some(std::time::Instant::now() + Duration::from_millis(100));
813	                return Ok(ScreenAction::Refresh);
814	            }
815	            Action::CheckStatus
816	                if state.popup_type == PackagePopupType::None && !state.is_checking =>
817	            {
818	                // Check Selected
819	                if let Some(idx) = state.list_state.selected() {
820	                    if idx < state.packages.len() {
821	                        // Reset status for this one
822	                        if state.package_statuses.len() != state.packages.len() {
823	                            state.package_statuses =
824	                                vec![PackageStatus::Unknown; state.packages.len()];
825	                        }
826	                        state.package_statuses[idx] = PackageStatus::Unknown;
827	                        state.is_checking = true;
828	                        state.checking_index = Some(idx);
829	                        // Mark that we're checking only the selected package (not all)
830	                        // We'll use checking_index = Some(idx) to indicate "check selected" mode
831	                        state.checking_delay_until =
832	                            Some(std::time::Instant::now() + Duration::from_millis(100));
833	                        return Ok(ScreenAction::Refresh);
834	                    }
835	                }
836	            }
837	            Action::Install if state.popup_type == PackagePopupType::None && !state.is_checking => {
838	                // Install Missing
839	                // Logic usually just starts installing.
840	                // We can check if any are missing and trigger the InstallMissingPackages action
841	                // which App will handle (or we handle internally if we can).
842	                // Wait, we moved 'process_installation_step' here. So we can start it here!
843	                // But we need to detect WHICH packages are missing.
844	
845	                let missing_count = state
846	                    .package_statuses
847	                    .iter()
848	                    .filter(|s| matches!(s, PackageStatus::NotInstalled))
849	                    .count();
850	                if missing_count > 0 {
851	                    // Trigger installation logic
852	                    return Ok(ScreenAction::InstallMissingPackages);
853	                }
854	            }
855	            Action::Create if state.popup_type == PackagePopupType::None && !state.is_checking => {
856	                self.start_add_package()?;
857	                return Ok(ScreenAction::Refresh);
858	            }
859	            Action::Edit if state.popup_type == PackagePopupType::None && !state.is_checking => {
860	                if let Some(idx) = state.list_state.selected() {
861	                    if idx < state.packages.len() {
862	                        self.start_edit_package(idx)?;
863	                        return Ok(ScreenAction::Refresh);
864	                    }
865	                }
866	            }
867	            Action::Delete if state.popup_type == PackagePopupType::None && !state.is_checking => {
868	                if let Some(idx) = state.list_state.selected() {
869	                    if idx < state.packages.len() {
870	                        state.delete_index = Some(idx);
871	                        state.popup_type = PackagePopupType::Delete;
872	                        state.delete_confirm_input.clear();
873	                        return Ok(ScreenAction::Refresh);
874	                    }
875	                }
876	            }
877	            Action::Cancel | Action::Quit if !state.is_checking => {
878	                return Ok(ScreenAction::Navigate(ScreenEnum::MainMenu));
879	            }
880	            Action::Cancel | Action::Quit if state.is_checking => {
881	                // If checking, maybe cancel check?
882	                state.is_checking = false;
883	                return Ok(ScreenAction::Refresh);
884	            }
885	            Action::Import if state.popup_type == PackagePopupType::None && !state.is_checking => {
886	                self.start_import()?;
887	                return Ok(ScreenAction::Refresh);
888	            }
889	            _ => {}
890	        }
891	        Ok(ScreenAction::None)
892	    }
