964	    fn start_import(&mut self) -> Result<()> {
965	        use crate::services::PackageService;
966	        use crate::ui::ImportFocus;
967	        use crate::utils::{DiscoverySource, PackageDiscoveryService};
968	
969	        let state = &mut self.state;
970	        state.popup_type = PackagePopupType::Import;
971	
972	        // Get available package managers from PackageService, then convert to DiscoverySources
973	        // This filters out managers that don't support discovery (e.g., Custom, language managers)
974	        let available_managers = PackageService::get_available_managers();
975	        state.import_available_sources = available_managers
976	            .iter()
977	            .filter_map(DiscoverySource::from_package_manager)
978	            .collect();
979	
