1071	    /// Poll the async discovery receiver for updates (non-blocking)
1072	    fn poll_import_discovery(&mut self) -> bool {
1073	        use crate::ui::ImportSourceCache;
1074	        use crate::utils::DiscoveryStatus;
1075	        use std::sync::mpsc::TryRecvError;
1076	        use std::time::Instant;
1077	
1078	        let rx = match self.state.import_discovery_rx.as_ref() {
1079	            Some(rx) => rx,
1080	            None => return false,
1081	        };
1082	
1083	        match rx.try_recv() {
1084	            Ok(status) => {
1085	                match status {
1086	                    DiscoveryStatus::Started(_source) => {
1087	                        // Just started, keep waiting
1088	                    }
1089	                    DiscoveryStatus::Complete { source, packages } => {
1090	                        // Filter out packages that are already added (by binary name)
1091	                        let existing_binaries: std::collections::HashSet<String> = self
1092	                            .state
1093	                            .packages
1094	                            .iter()
1095	                            .map(|p| p.binary_name.to_lowercase())
1096	                            .collect();
1097	
1098	                        let filtered_packages: Vec<_> = packages
1099	                            .into_iter()
1100	                            .filter(|p| {
1101	                                let binary = p
1102	                                    .binary_name
1103	                                    .as_ref()
1104	                                    .unwrap_or(&p.package_name)
1105	                                    .to_lowercase();
1106	                                !existing_binaries.contains(&binary)
1107	                            })
1108	                            .collect();
1109	
1110	                        // Store in per-source cache
1111	                        self.state.import_source_cache.insert(
1112	                            source,
1113	                            ImportSourceCache {
1114	                                packages: filtered_packages,
1115	                                discovered_at: Instant::now(),
1116	                                selected: std::collections::HashSet::new(),
1117	                            },
1118	                        );
1119	
1120	                        // Update list state
1121	                        if !self.state.import_current_packages().is_empty() {
1122	                            self.state.import_list_state.select(Some(0));
1123	                        }
1124	
1125	                        self.state.import_loading = false;
1126	                        self.state.import_discovery_rx = None;
1127	                    }
1128	                    DiscoveryStatus::Failed { source: _, error } => {
1129	                        warn!("Discovery failed: {}", error);
1130	                        self.state.import_loading = false;
1131	                        self.state.import_discovery_rx = None;
1132	                    }
1133	                    DiscoveryStatus::NoSourcesAvailable => {
1134	                        self.state.import_loading = false;
1135	                        self.state.import_discovery_rx = None;
1136	                    }
1137	                }
1138	                true // Got a message
1139	            }
1140	            Err(TryRecvError::Empty) => false, // No message yet
1141	            Err(TryRecvError::Disconnected) => {
1142	                // Thread finished without sending Complete
1143	                self.state.import_loading = false;
1144	                self.state.import_discovery_rx = None;
1145	                true
1146	            }
1147	        }
1148	    }
