1701	    fn handle_import_popup_event(
1702	        &mut self,
1703	        key: crossterm::event::KeyEvent,
1704	        config: &Config,
1705	    ) -> Result<ScreenAction> {
1706	        use crate::ui::ImportFocus;
1707	
1708	        let action = config.keymap.get_action(key.code, key.modifiers);
1709	
1710	        // Global actions (work regardless of focus)
1711	        if let Some(action) = action {
1712	            match action {
1713	                Action::Cancel | Action::Quit => {
1714	                    self.state.popup_type = PackagePopupType::None;
1715	                    self.state.import_selected.clear();
1716	                    self.state.import_filter.clear();
1717	                    return Ok(ScreenAction::Refresh);
1718	                }
1719	                Action::Confirm if !self.state.import_selected.is_empty() => {
1720	                    return self.import_selected_packages(config);
1721	                }
1722	                Action::SelectAll => {
1723	                    let filtered = self.get_filtered_import_packages();
1724	                    for &idx in &filtered {
1725	                        self.state.import_selected.insert(idx);
1726	                    }
1727	                    return Ok(ScreenAction::Refresh);
1728	                }
1729	                Action::DeselectAll => {
1730	                    self.state.import_selected.clear();
1731	                    return Ok(ScreenAction::Refresh);
1732	                }
1733	                _ => {}
1734	            }
1735	        }
1736	
1737	        // Focus cycling with Tab/Shift+Tab
1738	        if key.code == KeyCode::Tab && !key.modifiers.contains(KeyModifiers::SHIFT) {
1739	            // Only cycle focus if we have tabs to show
1740	            if self.state.import_available_sources.len() > 1 {
1741	                self.state.import_focus = match self.state.import_focus {
1742	                    ImportFocus::Tabs => ImportFocus::Filter,
1743	                    ImportFocus::Filter => ImportFocus::List,
1744	                    ImportFocus::List => ImportFocus::Tabs,
1745	                };
1746	            } else {
1747	                // No tabs or only one source - cycle between Filter and List
1748	                self.state.import_focus = match self.state.import_focus {
1749	                    ImportFocus::Tabs => ImportFocus::Filter,
1750	                    ImportFocus::Filter => ImportFocus::List,
1751	                    ImportFocus::List => ImportFocus::Filter,
1752	                };
1753	            }
1754	            return Ok(ScreenAction::Refresh);
1755	        }
1756	        if key.code == KeyCode::BackTab {
1757	            if self.state.import_available_sources.len() > 1 {
1758	                self.state.import_focus = match self.state.import_focus {
1759	                    ImportFocus::Tabs => ImportFocus::List,
1760	                    ImportFocus::Filter => ImportFocus::Tabs,
1761	                    ImportFocus::List => ImportFocus::Filter,
1762	                };
1763	            } else {
1764	                self.state.import_focus = match self.state.import_focus {
1765	                    ImportFocus::Tabs => ImportFocus::List,
1766	                    ImportFocus::Filter => ImportFocus::List,
1767	                    ImportFocus::List => ImportFocus::Filter,
1768	                };
1769	            }
1770	            return Ok(ScreenAction::Refresh);
1771	        }
1772	
1773	        // Focus-specific handling
1774	        match self.state.import_focus {
1775	            ImportFocus::Tabs => self.handle_import_tabs_input(key, config),
1776	            ImportFocus::Filter => self.handle_import_filter_input(key, config),
1777	            ImportFocus::List => self.handle_import_list_input(key, config),
1778	        }
1779	    }
