1781	    fn handle_import_tabs_input(
1782	        &mut self,
1783	        key: crossterm::event::KeyEvent,
1784	        config: &Config,
1785	    ) -> Result<ScreenAction> {
1786	        use crate::ui::ImportFocus;
1787	
1788	        let action = config.keymap.get_action(key.code, key.modifiers);
1789	
1790	        if let Some(action) = action {
1791	            match action {
1792	                Action::MoveLeft => {
1793	                    if self.state.import_active_tab > 0 {
1794	                        self.switch_import_tab(self.state.import_active_tab - 1);
1795	                    }
1796	                    return Ok(ScreenAction::Refresh);
1797	                }
1798	                Action::MoveRight => {
1799	                    if self.state.import_active_tab
1800	                        < self.state.import_available_sources.len().saturating_sub(1)
1801	                    {
1802	                        self.switch_import_tab(self.state.import_active_tab + 1);
1803	                    }
1804	                    return Ok(ScreenAction::Refresh);
1805	                }
1806	                Action::MoveDown => {
1807	                    // Move focus to filter
1808	                    self.state.import_focus = ImportFocus::Filter;
1809	                    return Ok(ScreenAction::Refresh);
1810	                }
1811	                _ => {}
1812	            }
1813	        }
