1818	        &mut self,
1819	        key: crossterm::event::KeyEvent,
1820	        config: &Config,
1821	    ) -> Result<ScreenAction> {
1822	        use crate::ui::ImportFocus;
1823	
1824	        let action = config.keymap.get_action(key.code, key.modifiers);
1825	
1826	        // Handle backspace
1827	        if let Some(Action::Backspace) = action {
1828	            self.state.import_filter.backspace();
1829	            self.reset_import_list_selection();
1830	            return Ok(ScreenAction::Refresh);
1831	        }
1832	
1833	        // Handle character input (exclude Space which is for ToggleSelect)
1834	        if let KeyCode::Char(c) = key.code {
1835	            if !key
1836	                .modifiers
1837	                .intersects(KeyModifiers::CONTROL | KeyModifiers::ALT | KeyModifiers::SUPER)
1838	                && c != ' '
1839	            {
1840	                self.state.import_filter.insert_char(c);
1841	                self.reset_import_list_selection();
1842	                return Ok(ScreenAction::Refresh);
1843	            }
1844	        }
1845	
1846	        // Space toggles selection (even when filter focused)
1847	        if let Some(Action::ToggleSelect) = action {
1848	            self.toggle_import_selection();
1849	            return Ok(ScreenAction::Refresh);
1850	        }
1851	
1852	        // Navigation moves focus
1853	        if let Some(action) = action {
1854	            match action {
1855	                Action::MoveUp => {
1856	                    if self.state.import_available_sources.len() > 1 {
1857	                        self.state.import_focus = ImportFocus::Tabs;
1858	                    }
1859	                    return Ok(ScreenAction::Refresh);
1860	                }
1861	                Action::MoveDown => {
1862	                    self.state.import_focus = ImportFocus::List;
1863	                    return Ok(ScreenAction::Refresh);
1864	                }
1865	                _ => {}
1866	            }
1867	        }
1868	
1869	        Ok(ScreenAction::None)
1870	    }
