1872	    fn handle_import_list_input(
1873	        &mut self,
1874	        key: crossterm::event::KeyEvent,
1875	        config: &Config,
1876	    ) -> Result<ScreenAction> {
1877	        let action = config.keymap.get_action(key.code, key.modifiers);
1878	
1879	        if let Some(action) = action {
1880	            match action {
1881	                Action::MoveUp => {
1882	                    let filtered = self.get_filtered_import_packages();
1883	                    if !filtered.is_empty() {
1884	                        let current = self.state.import_list_state.selected().unwrap_or(0);
1885	                        let new_idx = if current == 0 {
1886	                            filtered.len() - 1
1887	                        } else {
1888	                            current - 1
1889	                        };
1890	                        self.state.import_list_state.select(Some(new_idx));
1891	                    }
1892	                    return Ok(ScreenAction::Refresh);
1893	                }
1894	                Action::MoveDown => {
1895	                    let filtered = self.get_filtered_import_packages();
1896	                    if !filtered.is_empty() {
1897	                        let current = self.state.import_list_state.selected().unwrap_or(0);
1898	                        let new_idx = (current + 1) % filtered.len();
1899	                        self.state.import_list_state.select(Some(new_idx));
1900	                    }
1901	                    return Ok(ScreenAction::Refresh);
1902	                }
1903	                Action::ToggleSelect => {
1904	                    self.toggle_import_selection();
1905	                    return Ok(ScreenAction::Refresh);
1906	                }
1907	                _ => {}
1908	            }
1909	        }
1910	
1911	        Ok(ScreenAction::None)
1912	    }
