1914	    fn toggle_import_selection(&mut self) {
1915	        let filtered = self.get_filtered_import_packages();
1916	        if let Some(filtered_idx) = self.state.import_list_state.selected() {
1917	            if let Some(&original_idx) = filtered.get(filtered_idx) {
1918	                if self.state.import_selected.contains(&original_idx) {
1919	                    self.state.import_selected.remove(&original_idx);
1920	                } else {
1921	                    self.state.import_selected.insert(original_idx);
1922	                }
1923	            }
1924	        }
1925	    }
