1936	    fn get_filtered_import_packages(&self) -> Vec<usize> {
1937	        let filter = self.state.import_filter.text().to_lowercase();
1938	        let packages = self.state.import_current_packages();
1939	
1940	        packages
1941	            .iter()
1942	            .enumerate()
1943	            .filter(|(_, pkg)| {
1944	                if filter.is_empty() {
1945	                    return true;
1946	                }
1947	                pkg.package_name.to_lowercase().contains(&filter)
1948	                    || pkg
1949	                        .binary_name
1950	                        .as_ref()
1951	                        .is_some_and(|b| b.to_lowercase().contains(&filter))
1952	            })
1953	            .map(|(idx, _)| idx)
1954	            .collect()
1955	    }
