1957	    fn import_selected_packages(&mut self, config: &Config) -> Result<ScreenAction> {
1958	        // First, sync current tab's selection to cache so it's included in the loop
1959	        if let Some(current_source) = self
1960	            .state
1961	            .import_available_sources
1962	            .get(self.state.import_active_tab)
1963	        {
1964	            if let Some(cache) = self.state.import_source_cache.get_mut(current_source) {
1965	                cache.selected = self.state.import_selected.clone();
1966	            }
1967	        }
1968	
1969	        // Collect all packages to import first to avoid borrow issues
1970	        let mut all_packages_to_import = Vec::new();
1971	
1972	        for (source, cache) in &self.state.import_source_cache {
1973	            if cache.selected.is_empty() {
1974	                continue;
1975	            }
1976	
1977	            let manager = source.to_package_manager();
1978	
1979	            let packages: Vec<crate::utils::DiscoveredPackage> = cache
1980	                .selected
1981	                .iter()
1982	                .filter_map(|&idx| cache.packages.get(idx).cloned())
1983	                .collect();
1984	
1985	            for pkg in packages {
1986	                all_packages_to_import.push((manager.clone(), pkg));
1987	            }
1988	        }
1989	
1990	        let mut packages_imported = false;
1991	
1992	        for (manager, discovered) in all_packages_to_import {
1993	            let binary_name = discovered
1994	                .binary_name
1995	                .clone()
1996	                .unwrap_or_else(|| discovered.package_name.clone());
1997	
1998	            let package = PackageService::create_package(PackageCreationParams {
1999	                name: &discovered.package_name,
2000	                description: &discovered.description.clone().unwrap_or_default(),
2001	                manager: manager.clone(),
2002	                is_custom: false,
2003	                package_name: &discovered.package_name,
2004	                binary_name: &binary_name,
2005	                install_command: "",
2006	                existence_check: "",
2007	                manager_check: "",
2008	            });
2009	
2010	            match PackageService::add_package(&config.repo_path, &config.active_profile, package) {
2011	                Ok(packages) => {
2012	                    self.update_packages(packages, &config.active_profile);
2013	                    packages_imported = true;
2014	                }
2015	                Err(e) => {
2016	                    warn!(
2017	                        "Failed to import package {}: {}",
2018	                        discovered.package_name, e
2019	                    );
2020	                }
2021	            }
2022	        }
2023	
2024	        if !packages_imported {
2025	            return Ok(ScreenAction::Refresh);
2026	        }
2027	
2028	        // Clear all selections after import
2029	        for cache in self.state.import_source_cache.values_mut() {
2030	            cache.packages.retain(|_p| {
2031	                // Determine if we should keep it. Ideally we remove imported ones.
2032	                // But complex to track which exact ones succeeded.
2033	                // For simplicity, just clearing selection is enough UX.
2034	                // The next discovery will filter them out anyway.
2035	                true
2036	            });
2037	            cache.selected.clear();
2038	        }
2039	
2040	        // Close popup and trigger check
2041	        self.state.popup_type = PackagePopupType::None;
2042	        self.state.import_selected.clear();
2043	        self.state.import_filter.clear();
2044	        self.state.is_checking = true;
2045	
2046	        Ok(ScreenAction::Refresh)
2047	    }
